SELECT CASE WHEN unit_price >= 450 THEN 'high' WHEN unit_price >= 130 THEN 'mid' ELSE 'low' END unit_price_bucket, SUM(unit_price) total_unit_price, COUNT(*) cnt, SUM(SUM(unit_price)) OVER (ORDER BY CASE WHEN unit_price >= 450 THEN 'high' WHEN unit_price >= 130 THEN 'mid' ELSE 'low' END) AS cumulative_unit_price FROM order_items WHERE quantity >= 7 GROUP BY CASE WHEN unit_price >= 450 THEN 'high' WHEN unit_price >= 130 THEN 'mid' ELSE 'low' END ORDER BY total_unit_price DESC;
